describe("replaceTag", () => {
  it("replaces a single tag", () => {
    const input = "<div>before</div><span>replace me</span><div>after</div>";
    const output = "<div>before</div><p>new tag</p><div>after</div>";
    expect(replaceTag(input, "span", "<p>new tag</p>")).toEqual(output);
  });

  it("replaces only the first instance of a tag", () => {
    const input =
      "<div>before</div><span>replace me</span><span>do not replace me</span><div>after</div>";
    const output =
      "<div>before</div><p>new tag</p><span>do not replace me</span><div>after</div>";
    expect(replaceTag(input, "span", "<p>new tag</p>")).toEqual(output);
  });

  it("does not modify input when tag not found", () => {
    const input = "<div>before</div><p>do not replace me</p><div>after</div>";
    expect(replaceTag(input, "span", "<p>new tag</p>")).toEqual(input);
  });

  it("does not treat a longer tag name that starts with the tag name as a match", () => {
    // `<cards>` and `<card2>` share the `card` prefix; only `<card>` is the target.
    for (const longer of ["cards", "card2", "card_x"]) {
      const input = `<${longer}>keep</${longer}><card>replace me</card>`;
      expect(replaceTag(input, "card", "<p>new</p>")).toEqual(
        `<${longer}>keep</${longer}><p>new</p>`,
      );
    }
  });

  it("preserves tag attributes", () => {
    const input =
      '<div>before</div><span class="important">replace me</span><div>after</div>';
    const output =
      '<div>before</div><p class="important">new tag</p><div>after</div>';
    expect(
      replaceTag(input, "span", '<p class="important">new tag</p>'),
    ).toEqual(output);
  });

  it("is case-insensitive", () => {
    const input = "<div>before</div><SPAN>replace me</SPAN><div>after</div>";
    const output = "<div>before</div><p>new tag</p><div>after</div>";
    expect(replaceTag(input, "span", "<p>new tag</p>")).toEqual(output);
  });
});

describe("getTag", () => {
  const htmlString = `
    <div class="container">
      <h1>Welcome to my website</h1>
      <p>This is a test paragraph</p>
    </div>
  `;
  // Test component list with extra metadata — cast because these have non-standard properties
  const componentList = {
    div: { className: "container" },
    h1: { style: { fontWeight: "bold" } },
  } as unknown as ComponentList;

  it("returns content and inner content of tag", () => {
    const tagName = "p";
    const expectedOutput = {
      content: "<p>This is a test paragraph</p>",
      innerContent: "This is a test paragraph",
    };
    expect(getTag(htmlString, tagName)).toEqual(expectedOutput);
  });

  it("returns empty object when tag not found", () => {
    const tagName = "span";
    expect(getTag(htmlString, tagName)).toEqual({});
  });

  it("returns content, inner content and component properties", () => {
    const tagName = "h1";
    const expectedOutput = {
      content: "<h1>Welcome to my website</h1>",
      innerContent: "Welcome to my website",
      style: { fontWeight: "bold" },
    };
    expect(getTag(htmlString, tagName, componentList)).toEqual(expectedOutput);
  });

  it("ignores tags inside HTML comments when extracting body or component tags", () => {
    const html = `<!DOCTYPE html>
<html>
<head></head>
<body>
  <div>
    <!-- Example: <body> tag in comment -->
    <p>Content</p>
  </div>
</body>
</html>`;
    const result = getTag(html, "body");
    expect(result.innerContent).toBeDefined();
    expect(result.innerContent).toContain("<p>Content</p>");
  });

  it("ignores component tags inside HTML comments", () => {
    const cList: ComponentList = {
      "my-comp": { fileName: "my-comp.html", fileContent: "<div>comp</div>" },
    };
    const html = `<div><!-- <my-comp></my-comp> --></div>`;
    const result = getFirstComponent(html, cList);
    expect(result.name).toBeUndefined();
  });
});

describe("getFirstComponent and getTag on the request path", () => {
  const list = (): ComponentList => ({
    "srv-card": { fileName: "srv-card.html", fileContent: "<div></div>" },
    "srv-card-wide": { fileName: "wide.html", fileContent: "<div></div>" },
    "plain-box": { fileName: "plain-box.html", fileContent: "<p></p>" },
  });

  it("keys a frozen list's tag regex on identity: its names are read once, not on every call", () => {
    const frozen = Object.freeze(list());
    const keys = vi.spyOn(Object, "keys");
    try {
      for (let i = 0; i < 5; i++)
        expect(
          getFirstComponent(`<p>x</p><plain-box></plain-box>`, frozen).name,
        ).toBe("plain-box");
      expect(keys.mock.calls.filter(([o]) => o === frozen).length).toBe(1);
    } finally {
      keys.mockRestore();
    }
  });

  it("mayContainComponent is false only when no tag names a listed component", () => {
    const frozen = Object.freeze(list());
    expect(mayContainComponent("plain text", frozen)).toBe(false);
    expect(mayContainComponent("<p>srv-card</p><srv-cards>", frozen)).toBe(
      false,
    );
    expect(mayContainComponent("<p>x</p><SRV-CARD a=1>", frozen)).toBe(true);
    expect(mayContainComponent("<plain-box/>", frozen)).toBe(true);
    // Conservative: a name in raw text still says maybe; the search decides.
    const inScript = `<script>"<plain-box></plain-box>"</script>`;
    expect(mayContainComponent(inScript, frozen)).toBe(true);
    expect(getFirstComponent(inScript, frozen)).toEqual({});
    expect(mayContainComponent("<plain-box>", {})).toBe(false);
  });

  it("a list that is not frozen is still re-read, so a renamed component is found", () => {
    const mutable = list();
    expect(getFirstComponent("<plain-box></plain-box>", mutable).name).toBe(
      "plain-box",
    );
    delete mutable["plain-box"];
    mutable["other-box"] = { fileContent: "<p></p>" };
    expect(getFirstComponent("<other-box></other-box>", mutable).name).toBe(
      "other-box",
    );
    expect(getFirstComponent("<plain-box></plain-box>", mutable)).toEqual({});
  });

  it("misuse: a list searched, edited, then frozen is matched against its names after the edit", () => {
    // The identity shortcut holds only for a regex built while the list was
    // already frozen; one cached before the freeze may predate an edit.
    const late = list();
    expect(getFirstComponent("<srv-card></srv-card>", late).name).toBe(
      "srv-card",
    );
    delete late["plain-box"];
    late["late-box"] = { fileContent: "<p></p>" };
    Object.freeze(late);
    expect(getFirstComponent("<late-box></late-box>", late).name).toBe(
      "late-box",
    );
    expect(mayContainComponent("<late-box></late-box>", late)).toBe(true);
    expect(getFirstComponent("<plain-box></plain-box>", late)).toEqual({});
  });

  it("misuse: an in-place edit that keeps the key count, first and last key still re-reads the names", () => {
    const edited: ComponentList = {
      "a-x": { fileContent: "<i></i>" },
      "b-x": { fileContent: "<i></i>" },
      "c-x": { fileContent: "<i></i>" },
    };
    expect(getFirstComponent("<a-x></a-x>", edited).name).toBe("a-x");
    delete edited["b-x"];
    delete edited["c-x"];
    edited["z-x"] = { fileContent: "<i></i>" };
    edited["c-x"] = { fileContent: "<i></i>" };
    expect(getFirstComponent("<p><z-x></z-x></p>", edited).name).toBe("z-x");
    expect(mayContainComponent("<z-x></z-x>", edited)).toBe(true);
    // A removed name never matches with no list entry behind it.
    expect(getFirstComponent("<p><b-x></b-x></p>", edited)).toEqual({});
    expect(mayContainComponent("<b-x></b-x>", edited)).toBe(false);
  });

  it("repeated and resumed searches on one list agree with a fresh search, longest name first", () => {
    const frozen = Object.freeze(list());
    const html = `<srv-card-wide></srv-card-wide> <srv-card a="<srv-card>"></srv-card> <plain-box/>`;
    const seen: Array<[string | undefined, number | undefined]> = [];
    let from = 0;
    for (let i = 0; i < 4; i++) {
      const found = getFirstComponent(html, frozen, undefined, from) as {
        name?: string;
        index?: number;
        endIndex?: number;
      };
      seen.push([found.name, found.index]);
      if (found.endIndex === undefined) break;
      from = found.endIndex;
    }
    expect(seen).toEqual([
      ["srv-card-wide", 0],
      ["srv-card", 32],
      ["plain-box", 69],
      [undefined, undefined],
    ]);
    // A second pass over the same list and string finds the same first tag.
    expect(getFirstComponent(html, frozen, undefined, 5).index).toBe(32);
    expect(getFirstComponent(html, frozen).index).toBe(0);
  });

  it("keeps the index fields off the enumerable result, and pairs a close tag written with case or space", () => {
    const frozen = Object.freeze(list());
    const html = `<i>a</i><SRV-CARD x="1">in<srv-card></srv-card></Srv-Card  ><b>after</b>`;
    const found = getFirstComponent(html, frozen) as Record<string, unknown>;
    expect(found).toEqual({
      name: "srv-card",
      index: 8,
      content: `<SRV-CARD x="1">in<srv-card></srv-card></Srv-Card  >`,
      innerContent: "in<srv-card></srv-card>",
      fileName: "srv-card.html",
      fileContent: "<div></div>",
    });
    expect(Object.keys(found)).not.toContain("startIndex");
    expect([
      found.startIndex,
      found.contentStart,
      found.closeIndex,
      found.endIndex,
    ]).toEqual([8, 24, 47, 47 + "</Srv-Card  >".length]);
    const tag = getTag(html, "srv-card", frozen) as Record<string, unknown>;
    expect(Object.keys(tag).sort()).toEqual([
      "content",
      "fileContent",
      "fileName",
      "innerContent",
    ]);
    expect(tag.endIndex).toBe(found.endIndex);
    // An unclosed tag ends at its open tag; a self-closing one at its `/>`.
    const open = getTag(`<srv-card a=1>tail`, "srv-card") as Record<
      string,
      unknown
    >;
    expect([open.content, open.closeIndex, open.endIndex]).toEqual([
      "<srv-card a=1>",
      -1,
      14,
    ]);
  });
});

describe("getFirstComponent", () => {
  const componentList = {
    "tag-a": {
      fileName: "components/tag-a.html",
      fileContent: "<div><p>tag-a</p><div data-bascik-slot></div></div>",
    },
    "tag-b": {
      fileName: "components/tag-b.html",
      fileContent: "<div><p>tag-b</p><div data-bascik-slot></div></div>",
    },
    "tag-c": {
      fileName: "components/tag-c.html",
      fileContent: "<div><p>tag-c</p><div data-bascik-slot></div></div>",
    },
  } satisfies ComponentList;

  const htmlString = `<h1>Index</h1><tag-b></tag-b><tag-c></tag-c><my-footer></my-footer>`;

  it("should return an empty object when passed an empty string", () => {
    expect(getFirstComponent("", componentList)).toEqual({});
  });

  it("should return an empty object when no component is found in the string", () => {
    const htmlString = "<div><p>Hello World!</p></div>";
    expect(getFirstComponent(htmlString, componentList)).toEqual({});
  });

  it("should return the first component found in the string", () => {
    const expected = {
      name: "tag-b",
      index: 14,
      content: "<tag-b></tag-b>",
      innerContent: "",
      fileName: "components/tag-b.html",
      fileContent: "<div><p>tag-b</p><div data-bascik-slot></div></div>",
    };
    expect(getFirstComponent(htmlString, componentList)).toEqual(expected);
  });

  describe("getFirstComponent – missing from list", () => {
    it("should return an object with name but no fileContent if matched but not in list (edge case)", () => {
      // This shouldn't happen normally because the regex is built from keys
      const html = "<unknown-comp></unknown-comp>";
      const componentList: ComponentList = {};
      // Mock the regex to include unknown-comp
      const result = getTag(html, "unknown-comp", componentList);
      expect(result.content).toBeDefined();
      expect(result.fileContent).toBeUndefined();
    });
  });

  describe("getFirstComponent – dangling closing tag", () => {
    it("should not match a closing tag if it appears without an opening tag", () => {
      const html = "<div></code-block></div>";
      const componentList: ComponentList = {
        "code-block": { fileContent: "<div></div>" },
      };
      const result = getFirstComponent(html, componentList);
      expect(result.name).toBeUndefined();
    });
  });

  it("does not match a longer hyphenated tag when only its prefix is registered", () => {
    const cardOnly: ComponentList = {
      card: { fileContent: "<article>card</article>" },
    };

    expect(
      getFirstComponent("<card-header>Heading</card-header>", cardOnly),
    ).toEqual({});
  });

  it("refreshes its regex when component names change without changing key count", () => {
    const mutableList: ComponentList = {
      "old-card": { fileContent: "<article>old</article>" },
    };
    expect(getFirstComponent("<old-card></old-card>", mutableList).name).toBe(
      "old-card",
    );

    delete mutableList["old-card"];
    mutableList["new-card"] = { fileContent: "<article>new</article>" };

    expect(getFirstComponent("<new-card></new-card>", mutableList).name).toBe(
      "new-card",
    );
  });

  it("matches equal-length component names consistently regardless of insertion order", () => {
    const alphaFirst: ComponentList = {
      "alpha-box": { fileContent: "<div>alpha</div>" },
      "bravo-box": { fileContent: "<div>bravo</div>" },
    };
    const bravoFirst: ComponentList = {
      "bravo-box": { fileContent: "<div>bravo</div>" },
      "alpha-box": { fileContent: "<div>alpha</div>" },
    };
    const html = "<bravo-box></bravo-box><alpha-box></alpha-box>";

    expect(getFirstComponent(html, alphaFirst).name).toBe("bravo-box");
    expect(getFirstComponent(html, bravoFirst).name).toBe("bravo-box");
  });

  describe("getFirstComponent – attribute-aware discovery", () => {
    const auditLabel: ComponentList = {
      "audit-label": { fileContent: "<span>label</span>" },
    };

    it("does not match a component tag inside a double-quoted attribute value", () => {
      const html = '<p title="Use <audit-label> exactly">Visible text</p>';
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("ignores closing component tags inside quoted attributes", () => {
      const html =
        '<audit-label><p title="Use </audit-label> exactly">text</p></audit-label>';
      expect(getFirstComponent(html, auditLabel).content).toBe(html);
    });

    it("handles many tag-like attribute tokens without recursive rescanning", () => {
      const mentions = "<span><audit-label></audit-label>".repeat(1000);
      const html = `<p title="${mentions}">text</p><audit-label/>`;
      const started = performance.now();
      expect(getFirstComponent(html, auditLabel).content).toBe(
        "<audit-label/>",
      );
      expect(getTag(html, "audit-label").content).toBe("<audit-label/>");
      expect(replaceTag(html, "audit-label", "replacement")).toBe(
        `<p title="${mentions}">text</p>replacement`,
      );
      expect(performance.now() - started).toBeLessThan(1000);
    });

    it("does not match a component tag inside a single-quoted attribute value", () => {
      const html = "<p title='Use <audit-label> exactly'>Visible text</p>";
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("does not match a component tag inside an unquoted attribute value", () => {
      const html = "<p data-note=Use<audit-label>Visible text</p>";
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("still finds a real component after an attribute that mentions it", () => {
      const html =
        '<p title="Use <audit-label> exactly">Visible text</p><audit-label></audit-label>';
      const result = getFirstComponent(html, auditLabel);
      expect(result.name).toBe("audit-label");
      expect(result.content).toBe("<audit-label></audit-label>");
    });

    it("still finds a real component before an attribute that mentions it", () => {
      const html =
        '<audit-label></audit-label><p title="Use <audit-label> exactly">Visible text</p>';
      const result = getFirstComponent(html, auditLabel);
      expect(result.name).toBe("audit-label");
      expect(result.content).toBe("<audit-label></audit-label>");
    });

    it("does not match a component tag inside a quoted attribute value with a quoted >", () => {
      const html =
        '<p title="Use <audit-label> exactly > here">Visible text</p>';
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("does not match a component tag inside a multiline quoted attribute value", () => {
      const html = `<p
        title="Use <audit-label> exactly"
        class="x">Visible text</p>`;
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("still finds a real component with multiline attributes and quoted >", () => {
      const html = `<audit-label
        title="a > b"
        class="x"></audit-label>`;
      const result = getFirstComponent(html, auditLabel);
      expect(result.name).toBe("audit-label");
      expect(result.content).toBe(
        `<audit-label
        title="a > b"
        class="x"></audit-label>`,
      );
    });

    it("does not match a component tag inside a quoted attribute value when the tag is self-closing", () => {
      const html = '<p title="Use <audit-label/> exactly">Visible text</p>';
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("does not match a component tag inside a quoted attribute value when the tag is paired", () => {
      const html =
        '<p title="Use <audit-label>exactly</audit-label> here">Visible text</p>';
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("does not match a component tag inside a quoted value that itself contains a <", () => {
      const html = '<p title="a < b <audit-label>">x</p>';
      expect(getFirstComponent(html, auditLabel)).toEqual({});
    });

    it("pairs a real component correctly when a later attribute mentions it", () => {
      const html =
        '<audit-label>a</audit-label><p title="Use <audit-label> exactly">b</p>';
      const result = getFirstComponent(html, auditLabel);
      expect(result.name).toBe("audit-label");
      expect(result.content).toBe("<audit-label>a</audit-label>");
      expect(result.innerContent).toBe("a");
    });
  });
});

describe("getTag – component name boundary", () => {
  it("matches a component closing tag with whitespace before the terminator", () => {
    expect(getTag("<my-card>content</my-card >", "my-card")).toEqual({
      content: "<my-card>content</my-card >",
      innerContent: "content",
    });
  });

  it("keeps a complete quoted opening tag when the component is unclosed", () => {
    expect(getTag('<my-card title="a > b">tail', "my-card")).toEqual({
      content: '<my-card title="a > b">',
      innerContent: "",
    });
  });

  it("does not parse a longer hyphenated tag as a shorter component", () => {
    expect(getTag("<card-header>Heading</card-header>", "card")).toEqual({});
  });
});

