describe("extractProps", () => {
  it("extracts a single prop", () => {
    expect(
      extractProps('<my-comp data-bascik-prop-title="Hello"></my-comp>'),
    ).toEqual({ title: "Hello" });
  });

  it("extracts multiple props", () => {
    expect(
      extractProps(
        '<my-comp data-bascik-prop-title="Hello" data-bascik-prop-href="/about"></my-comp>',
      ),
    ).toEqual({ title: "Hello", href: "/about" });
  });

  it("extracts whitespace-spaced and unquoted prop values and matches case-insensitively", () => {
    const props = extractProps(
      '<my-comp data-bascik-prop-ctaUrl = "/start" data-bascik-prop-variant=primary></my-comp>',
    );
    expect(props).toEqual({ ctaUrl: "/start", variant: "primary" });
    expect(injectProps("<span data-bascik-prop-variant></span>", props)).toBe(
      "<span>primary</span>",
    );
    expect(
      injectPropAttributes('<a data-bascik-attr-href="ctaurl">Go</a>', props),
    ).toBe('<a href="/start">Go</a>');
  });

  it("returns empty object when no props", () => {
    expect(extractProps("<my-comp></my-comp>")).toEqual({});
  });

  it("returns empty object for undefined input", () => {
    expect(extractProps(undefined)).toEqual({});
  });

  it("warns when a prop value contains its delimiting quote", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    extractProps('<my-comp data-bascik-prop-title="say "hello""></my-comp>');

    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("data-bascik-prop-title"),
    );
    warnSpy.mockRestore();
  });

  it("decodes entity-encoded quotes in extracted prop values", () => {
    expect(
      extractProps(
        '<my-comp data-bascik-prop-title="say &quot;hello&quot;" data-bascik-prop-caption="it&#39;s fine"></my-comp>',
      ),
    ).toEqual({ title: 'say "hello"', caption: "it's fine" });
  });

  it("does not treat a marker token inside another attribute's quoted value as a prop", () => {
    // The marker string appears only inside the `title` value, never as a
    // whole attribute name, so no prop may be fabricated from it.
    expect(
      extractProps(
        "<my-comp title=\"reference data-bascik-prop-doc='guide' now\"></my-comp>",
      ),
    ).toEqual({});
  });

  it("does not treat marker text in the opening tag when a marker is a real prop elsewhere", () => {
    expect(
      extractProps(
        '<my-comp data-bascik-prop-title="Hello" title="data-bascik-prop-title is used in docs"></my-comp>',
      ),
    ).toEqual({ title: "Hello" });
  });
});

describe("injectProps", () => {
  it("fills a receiver after a comment the browser ends at --!>, <!--> or <!--->", () => {
    // These close a comment in the browser, so the receiver after one is live
    // markup; a later `-->` must not stretch the comment over it.
    for (const comment of ["<!-- note --!>", "<!-->", "<!--->"])
      expect(
        injectProps(
          `${comment}<p data-bascik-prop-title>f</p><!-- <b data-bascik-prop-title></b> -->`,
          { title: "Hi" },
        ),
      ).toBe(`${comment}<p>Hi</p><!-- <b data-bascik-prop-title></b> -->`);
  });

  it("leaves a receiver inside an unclosed comment as written", () => {
    expect(
      injectProps(
        "<p data-bascik-prop-title>f</p><!-- <b data-bascik-prop-title></b>",
        {
          title: "Hi",
        },
      ),
    ).toBe("<p>Hi</p><!-- <b data-bascik-prop-title></b>");
  });

  it("misuse: a template that repeats a prop receiver thousands of times is filled in linear time", () => {
    // Splicing each receiver into the growing result, and re-masking the
    // whole template for each close search, took seconds at 5000 receivers.
    const count = 5000;
    const template = `<div>${"<b data-bascik-prop-title>f</b><i data-bascik-prop-unset>u</i>".repeat(count)}</div>`;
    const value = "y".repeat(2000);
    const started = performance.now();
    const out = injectProps(template, { title: value });
    const elapsed = performance.now() - started;
    expect(out).toBe(`<div>${`<b>${value}</b><i>u</i>`.repeat(count)}</div>`);
    expect(elapsed).toBeLessThan(1500);
  });

  it("misuse: thousands of unfilled markers in a large template are stripped in linear time", () => {
    const count = 5000;
    const filler = "z".repeat(2000);
    const template = `<div>${`<i data-bascik-prop-unset class="c">${filler}</i>`.repeat(count)}</div>`;
    const started = performance.now();
    const out = injectProps(template, { other: "v" });
    const elapsed = performance.now() - started;
    expect(out).toBe(
      `<div>${`<i class="c">${filler}</i>`.repeat(count)}</div>`,
    );
    expect(elapsed).toBeLessThan(1500);
  });

  it("misuse: thousands of receivers whose fallback holds a balanced script, style or textarea are filled in linear time", () => {
    // A balanced raw-text element cannot change how anything after it is
    // masked, yet each one used to re-mask the whole template.
    const count = 5000;
    const template = `<div>${"<b data-bascik-prop-t><script>1</script></b><i data-bascik-prop-t><style>a{}</style><textarea>q</textarea></i>".repeat(count)}</div>`;
    const started = performance.now();
    const out = injectProps(template, { t: "x" });
    const elapsed = performance.now() - started;
    expect(out).toBe(`<div>${"<b>x</b><i>x</i>".repeat(count)}</div>`);
    expect(elapsed).toBeLessThan(1500);
  });

  it("misuse: tens of thousands of unclosed receivers, or receivers closed only once at the end, cost linear time", () => {
    const count = 40_000;
    const started = performance.now();
    const unclosed = "<i data-bascik-prop-t>f".repeat(count);
    expect(injectProps(unclosed, { t: "x" })).toBe("<i>f".repeat(count));
    const tail = 3000;
    const closedOnce = `${"<i data-bascik-prop-t>f".repeat(tail)}</i>`;
    // Only the last receiver pairs with the one close; the rest stay
    // unfilled, exactly as a depth count from each of them finds.
    expect(injectProps(closedOnce, { t: "x" })).toBe(
      `${"<i>f".repeat(tail - 1)}<i>x</i>`,
    );
    expect(performance.now() - started).toBeLessThan(1500);
  });

  it.each([
    [
      "<b data-bascik-prop-t><script></b><b data-bascik-prop-t>in</b></script><b data-bascik-prop-t>after</b>",
      "<b><script></b><b data-bascik-prop-t>in</b></script><b>v</b>",
    ],
    [
      '<b data-bascik-prop-t><a title="<script>"></a></b><b data-bascik-prop-t>x</b></script><b data-bascik-prop-t>y</b>',
      '<b><a title="<script>"></a></b><b data-bascik-prop-t>x</b></script><b>y</b>',
    ],
    [
      "<b data-bascik-prop-t><script>s</script><style></b><b data-bascik-prop-t>z</b>",
      "<b>v</b><b>v</b>",
    ],
    [
      "<b data-bascik-prop-t>--></b><b data-bascik-prop-t>q</b>",
      "<b>v</b><b>v</b>",
    ],
    [
      "<b data-bascik-prop-t><!--</b>--><b data-bascik-prop-t>r</b>",
      "<b><!--</b>--><b>v</b>",
    ],
  ])(
    "misuse: unbalanced raw-text or comment syntax in or around a receiver is filled exactly as before: %j",
    (template, expected) => {
      // Outputs recorded from the splice-per-receiver implementation.
      expect(injectProps(template, { t: "v" })).toBe(expected);
    },
  );

  it("fills receivers around raw text, comments, self-closing markers and unclosed receivers exactly as before", () => {
    const template =
      '<b data-bascik-prop-t>1</b><script>"<b data-bascik-prop-t>"</script><!-- <b data-bascik-prop-t>c</b> --><br data-bascik-prop-t/><b data-bascik-prop-t><b>in</b></b><b data-bascik-prop-t>open';
    expect(injectProps(template, { t: "<&>" })).toBe(
      '<b>&lt;&amp;&gt;</b><script>"<b data-bascik-prop-t>"</script><!-- <b data-bascik-prop-t>c</b> --><br data-bascik-prop-t/><b>&lt;&amp;&gt;</b><b>open',
    );
  });

  it("injects a prop value as element inner content", () => {
    const template = "<p data-bascik-prop-title></p>";
    expect(injectProps(template, { title: "Hello" })).toBe("<p>Hello</p>");
  });

  it("removes the data-bascik-prop attribute from the output", () => {
    const result = injectProps("<p data-bascik-prop-title></p>", {
      title: "Hi",
    });
    expect(result).not.toContain("data-bascik-prop-title");
  });

  it("preserves other attributes on the element", () => {
    const template = '<p class="lead" data-bascik-prop-title></p>';
    expect(injectProps(template, { title: "Hello" })).toBe(
      '<p class="lead">Hello</p>',
    );
  });

  it("injects multiple props into different elements", () => {
    const template =
      "<h1 data-bascik-prop-heading></h1><p data-bascik-prop-body></p>";
    expect(injectProps(template, { heading: "Title", body: "Content" })).toBe(
      "<h1>Title</h1><p>Content</p>",
    );
  });

  it("replaces the full body of a receiver with nested same-tag elements", () => {
    const template =
      "<div data-bascik-prop-title><div>fallback</div><p>tail</p></div>";
    expect(injectProps(template, { title: "New" })).toBe("<div>New</div>");
  });

  it("does not modify template when prop name has no matching element", () => {
    const template = "<p>static</p>";
    expect(injectProps(template, { title: "Hello" })).toBe("<p>static</p>");
  });

  it("strips unused data-bascik-prop-* markers when prop is not provided", () => {
    const template = "<span data-bascik-prop-file></span>";
    expect(injectProps(template, {})).toBe("<span></span>");
  });

  it("strips unused marker even when other props are injected", () => {
    const template =
      "<p data-bascik-prop-lang></p><span data-bascik-prop-file></span>";
    const result = injectProps(template, { lang: "html" });
    expect(result).toContain("<p>html</p>");
    expect(result).not.toContain("data-bascik-prop-file");
    expect(result).toContain("<span></span>");
  });

  it("handles undefined fileContent gracefully", () => {
    expect(injectProps(undefined, {})).toBe("");
  });

  it("keeps marker text appearing in plain text content", () => {
    // The marker token is prose, not an attribute, so the unused-marker strip
    // must leave it untouched.
    expect(
      injectProps("<p>See the data-bascik-prop-title docs for details</p>", {}),
    ).toBe("<p>See the data-bascik-prop-title docs for details</p>");
  });

  it("keeps marker text appearing inside another attribute's quoted value", () => {
    // The marker is prose inside the title value, not a receiver attribute, so
    // it must survive both the injection loop and the unused-marker strip.
    expect(
      injectProps('<p title="see data-bascik-prop-title note">fallback</p>', {
        title: "Hi",
      }),
    ).toBe('<p title="see data-bascik-prop-title note">fallback</p>');
    expect(
      injectProps(
        '<p title="see data-bascik-prop-title note">fallback</p>',
        {},
      ),
    ).toBe('<p title="see data-bascik-prop-title note">fallback</p>');
  });

  it("keeps a child component prop declaration with spaces around the equals", () => {
    expect(injectProps('<p data-bascik-prop-title = "featured"></p>', {})).toBe(
      '<p data-bascik-prop-title = "featured"></p>',
    );
  });

  it("strips only the valueless marker attribute, not marker text in other attributes", () => {
    expect(
      injectProps(
        '<p class="data-bascik-prop-title" data-bascik-prop-title></p>',
        {},
      ),
    ).toBe('<p class="data-bascik-prop-title"></p>');
  });
});

describe("injectPropAttributes", () => {
  it("binds an attribute after a comment the browser ends at --!>, <!--> or <!--->", () => {
    for (const comment of ["<!-- note --!>", "<!-->", "<!--->"])
      expect(
        injectPropAttributes(
          `${comment}<a data-bascik-attr-href="link">About</a><!-- <a data-bascik-attr-href="link"> -->`,
          { link: "/about" },
        ),
      ).toBe(
        `${comment}<a href="/about">About</a><!-- <a data-bascik-attr-href="link"> -->`,
      );
  });

  it("injects a simple attribute and strips the directive", () => {
    const result = injectPropAttributes(
      '<a data-bascik-attr-href="link">About</a>',
      { link: "/about" },
    );
    expect(result).toBe('<a href="/about">About</a>');
    expect(result).not.toContain("data-bascik-attr-");
  });

  it("supports hyphenated aria and data attribute targets", () => {
    expect(
      injectPropAttributes(
        '<div data-bascik-attr-aria-label="label" data-bascik-attr-data-foo="foo"></div>',
        { label: "Details", foo: "bar" },
      ),
    ).toBe('<div aria-label="Details" data-foo="bar"></div>');
  });

  it("passes the target attribute name and value through `rewriteValue` before escaping (prompt 157)", () => {
    // A request-time renderer injects bindings after scoping and maps id
    // references per target; the same prop can land on an id-reference
    // target and a plain one, so the rewrite sees the target.
    const rewriteValue = vi.fn((target: string, value: string) =>
      target === "for" ? `scoped-${value}` : value,
    );
    expect(
      injectPropAttributes(
        '<label data-bascik-attr-for="p" data-bascik-attr-title="p">L</label>',
        { p: "x<y" },
        rewriteValue,
      ),
    ).toBe('<label for="scoped-x&lt;y" title="x&lt;y">L</label>');
    expect(rewriteValue.mock.calls).toEqual([
      ["for", "x<y"],
      ["title", "x<y"],
    ]);
  });

  it("routes its warnings through `warn` when given (prompt 157)", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    const warn = vi.fn();
    injectPropAttributes(
      '<div title="old" data-bascik-attr-title="t" data-bascik-attr-id></div>',
      { t: "new" },
      undefined,
      warn,
    );
    expect(warnSpy).not.toHaveBeenCalled();
    expect(warn.mock.calls.map(([message]) => message)).toEqual([
      expect.stringMatching(/Attribute binding conflict: attribute "title"/),
      expect.stringMatching(/Ignoring malformed data-bascik-attr-id/),
    ]);
    expect(
      extractProps('<x-c data-bascik-prop-t="say "hello""></x-c>', warn),
    ).toEqual({});
    expect(warn).toHaveBeenCalledTimes(3);
    expect(warnSpy).not.toHaveBeenCalled();
    warnSpy.mockRestore();
  });

  it("removes a missing-prop directive without adding the target attribute", () => {
    expect(injectPropAttributes('<img data-bascik-attr-src="image">', {})).toBe(
      "<img>",
    );
  });

  it("lets the prop override an existing target and warns with both names", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    expect(
      injectPropAttributes(
        '<a href="/old" data-bascik-attr-href="link">Read</a>',
        { link: "/new" },
      ),
    ).toBe('<a href="/new">Read</a>');
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('attribute "href"'),
    );
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('prop "link"'),
    );
    warnSpy.mockRestore();
  });

  it.each([
    ['say "hello"', "say &quot;hello&quot;"],
    ["<unsafe>", "&lt;unsafe&gt;"],
  ])("attribute-escapes %s", (value, escaped) => {
    expect(
      injectPropAttributes('<img data-bascik-attr-alt="text">', {
        text: value,
      }),
    ).toBe(`<img alt="${escaped}">`);
  });

  it("preserves replacement tokens verbatim", () => {
    expect(
      injectPropAttributes('<a data-bascik-attr-href="link"></a>', {
        link: "/$&/$1/$`",
      }),
    ).toBe('<a href="/$&amp;/$1/$`"></a>');
  });

  it("warns and strips a directive with no target attribute name", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    expect(
      injectPropAttributes('<div data-bascik-attr-="value"></div>', {
        value: "ignored",
      }),
    ).toBe("<div></div>");
    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining("malformed data-bascik-attr-"),
    );
    warnSpy.mockRestore();
  });

  it("allows one prop to drive content and an attribute independently", () => {
    const props = { label: "About" };
    const withAttribute = injectPropAttributes(
      '<a data-bascik-attr-aria-label="label"><span data-bascik-prop-label></span></a>',
      props,
    );
    expect(injectProps(withAttribute, props)).toBe(
      '<a aria-label="About"><span>About</span></a>',
    );
  });

  it("does not warn or strip when a directive token appears inside another attribute's quoted value", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    expect(
      injectPropAttributes(
        '<a title="see data-bascik-attr-href note" data-bascik-attr-href="link">Go</a>',
        { link: "/about" },
      ),
    ).toBe('<a title="see data-bascik-attr-href note" href="/about">Go</a>');
    expect(warnSpy).not.toHaveBeenCalled();
    warnSpy.mockRestore();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// Phase 4: Named slots
// ─────────────────────────────────────────────────────────────────────────────

describe("extractNamedSlotContent", () => {
  it("extracts a single named slot", () => {
    const inner = '<div data-bascik-slot="header"><h1>My Header</h1></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      header: "<h1>My Header</h1>",
    });
  });

  it("extracts multiple named slots", () => {
    const inner =
      '<div data-bascik-slot="header"><h1>H</h1></div>' +
      '<div data-bascik-slot="footer"><p>F</p></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      header: "<h1>H</h1>",
      footer: "<p>F</p>",
    });
  });

  it("returns empty object when no named slots", () => {
    expect(extractNamedSlotContent("<p>just content</p>")).toEqual({});
  });

  it("returns empty object for empty string", () => {
    expect(extractNamedSlotContent("")).toEqual({});
  });

  it("handles nested same-tag elements inside slot wrapper", () => {
    // The slot wrapper is a <div>. The content also contains a <div>.
    // The regex must close at the OUTER </div>, not the first inner one.
    const inner =
      '<div data-bascik-slot="example">' +
      '<p>Before</p><div style="nested"><span>Inner</span></div><p>After</p>' +
      "</div>";
    expect(extractNamedSlotContent(inner)).toEqual({
      example:
        '<p>Before</p><div style="nested"><span>Inner</span></div><p>After</p>',
    });
  });

  it("handles deeply nested same-tag elements", () => {
    const inner =
      '<div data-bascik-slot="x">' +
      "<div><div><p>deep</p></div></div>" +
      "</div>" +
      '<div data-bascik-slot="y"><span>y</span></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      x: "<div><div><p>deep</p></div></div>",
      y: "<span>y</span>",
    });
  });

  it("extracts a slot whose marker is preceded by other attributes", () => {
    const inner =
      '<div id="header-slot" data-bascik-slot="header"><h1>Custom Header</h1></div>';
    expect(extractNamedSlotContent(inner)).toEqual({
      header: "<h1>Custom Header</h1>",
    });
  });

  it("ignores the marker text inside a quoted attribute value", () => {
    const inner = "<p title='see data-bascik-slot=\"fake\" usage'>text</p>";
    expect(extractNamedSlotContent(inner)).toEqual({});
  });

  it("ignores named slots owned by a nested child component", () => {
    const inner =
      '<p>parent content</p><inner-demo><div data-bascik-slot="source-html">child content</div></inner-demo>';

    expect(extractNamedSlotContent(inner, new Set(["inner-demo"]))).toEqual({});
  });
});

describe("replaceNamedSlots", () => {
  it("misuse: a template that repeats named slot wrappers thousands of times is filled in linear time", () => {
    // Splicing each wrapper into the growing result copied it once per
    // wrapper, and each close search rescanned attribute state from the
    // start: 5000 wrappers took seconds. Linear work takes milliseconds.
    const count = 5000;
    const template = `<div>${'<i data-bascik-slot="s">f</i><b data-bascik-slot="Missing">fb</b>'.repeat(count)}</div>`;
    const content = "x".repeat(2000);
    const started = performance.now();
    const out = replaceNamedSlots(
      template,
      { S: content },
      new Set(["my-card"]),
    );
    const elapsed = performance.now() - started;
    expect(out).toBe(`<div>${`${content}fb`.repeat(count)}</div>`);
    expect(elapsed).toBeLessThan(1500);
  });

  it("misuse: thousands of usage wrappers are extracted in linear time, and the last fill of a repeated name wins", () => {
    const count = 5000;
    const inner = `${'<p>body</p><div data-bascik-slot="side">n</div>'.repeat(count - 1)}<div data-bascik-slot="side">last</div>`;
    const started = performance.now();
    const slots = extractNamedSlotContent(inner, new Set(["my-card"]));
    const defaults = extractDefaultSlotContent(inner, new Set(["my-card"]));
    const elapsed = performance.now() - started;
    expect(slots).toEqual({ side: "last" });
    expect(defaults).toBe("<p>body</p>".repeat(count - 1));
    expect(elapsed).toBeLessThan(1500);
  });

  it("misuse: tens of thousands of unclosed slot wrappers, or wrappers closed only once at the end, cost linear time", () => {
    const count = 40_000;
    const started = performance.now();
    const unclosed = '<i data-bascik-slot="s">f'.repeat(count);
    expect(replaceNamedSlots(unclosed, { s: "x" })).toBe(unclosed);
    expect(extractDefaultSlotContent(unclosed)).toBe(unclosed);
    const defaults = "<i data-bascik-slot>f".repeat(count);
    expect(replaceDefaultSlots(defaults, "x")).toBe(defaults);
    const tail = 3000;
    const closedOnce = `${'<i data-bascik-slot="s">f'.repeat(tail)}</i>`;
    // Only the last wrapper pairs with the one close.
    expect(replaceNamedSlots(closedOnce, { s: "x" })).toBe(
      `${'<i data-bascik-slot="s">f'.repeat(tail - 1)}x`,
    );
    const defaultsOnce = `${"<i data-bascik-slot>f".repeat(tail)}</i>`;
    expect(replaceDefaultSlots(defaultsOnce, "x")).toBe(
      `${"<i data-bascik-slot>f".repeat(tail - 1)}x`,
    );
    expect(performance.now() - started).toBeLessThan(1500);
  });

  it("fills wrappers in document order around text, nested same-tag fallbacks and wrappers inside a child usage", () => {
    const template =
      '<a>1<div data-bascik-slot="x"><div>fb</div></div>2<my-card><i data-bascik-slot="x">kept</i></my-card>3<i data-bascik-slot="y">y</i>4</a>';
    expect(replaceNamedSlots(template, { x: "X" }, new Set(["my-card"]))).toBe(
      '<a>1X2<my-card><i data-bascik-slot="x">kept</i></my-card>3y4</a>',
    );
  });

  it("replaces a named slot placeholder with provided content", () => {
    const template =
      '<footer><div data-bascik-slot="footer-links"></div></footer>';
    const slots = { "footer-links": "<a href='/'>Home</a>" };
    expect(replaceNamedSlots(template, slots)).toBe(
      "<footer><a href='/'>Home</a></footer>",
    );
  });

  it("removes an unfilled named slot placeholder", () => {
    const template =
      '<footer><div data-bascik-slot="footer-links"></div></footer>';
    expect(replaceNamedSlots(template, {})).toBe("<footer></footer>");
  });

  it("does not affect default data-bascik-slot", () => {
    const template =
      "<div><div data-bascik-slot></div>" +
      '<span data-bascik-slot="side"></span></div>';
    const slots = { side: "<p>sidebar</p>" };
    const result = replaceNamedSlots(template, slots);
    expect(result).toContain("<div data-bascik-slot></div>");
    expect(result).toContain("<p>sidebar</p>");
  });

  it("matches a marker preceded by other attributes", () => {
    const template =
      '<footer><div id="nav-slot" data-bascik-slot="navigation"><p>Default nav</p></div></footer>';
    expect(replaceNamedSlots(template, { navigation: "<nav>Menu</nav>" })).toBe(
      "<footer><nav>Menu</nav></footer>",
    );
  });

  it("keeps fallback content containing nested same-tag elements intact", () => {
    const template =
      '<section><div data-bascik-slot="x"><div>fallback</div></div></section>';
    expect(replaceNamedSlots(template, {})).toBe(
      "<section><div>fallback</div></section>",
    );
  });

  it("replaces a placeholder whose fallback has nested same-tag elements", () => {
    const template =
      '<section><div data-bascik-slot="x"><div>fallback</div></div></section>';
    expect(replaceNamedSlots(template, { x: "<p>filled</p>" })).toBe(
      "<section><p>filled</p></section>",
    );
  });

  it("does not replace named slots inside an unresolved child component", () => {
    const template =
      '<section><inner-demo><div data-bascik-slot="source-html">child fallback</div></inner-demo></section>';

    expect(replaceNamedSlots(template, {}, new Set(["inner-demo"]))).toBe(
      template,
    );
  });
});

describe("replaceDefaultSlots", () => {
  it("misuse: a template that repeats its default slot is replaced in linear time, and past the engine's string limit fails at once", () => {
    // Splicing into the growing result copied it once per marker: 2000
    // markers of 20000 characters took tens of seconds.
    const template = `<div>${"<i data-bascik-slot>f</i>".repeat(2000)}</div>`;
    const content = "x".repeat(20_000);
    const started = performance.now();
    const out = replaceDefaultSlots(template, content);
    expect(out).toBe(`<div>${content.repeat(2000)}</div>`);
    expect(() => replaceDefaultSlots(template, "x".repeat(300_000))).toThrow(
      /Invalid string length/,
    );
    expect(performance.now() - started).toBeLessThan(2000);
  });

  it("replaces every repeated marker with the content and keeps the text between them in order", () => {
    const template = `<a><b data-bascik-slot>1</b>-<c data-bascik-slot>2</c>-<d data-bascik-slot></d></a>`;
    expect(replaceDefaultSlots(template, "X")).toBe("<a>X-X-X</a>");
    expect(replaceDefaultSlots(template, "")).toBe("<a>1-2-</a>");
  });

  it("replaces a default slot marker with provided content", () => {
    const template = "<div><div data-bascik-slot></div></div>";
    expect(replaceDefaultSlots(template, "<p>content</p>")).toBe(
      "<div><p>content</p></div>",
    );
  });

  it("keeps fallback content when no content is provided", () => {
    const template = "<div><div data-bascik-slot><p>fallback</p></div></div>";
    expect(replaceDefaultSlots(template, "")).toBe(
      "<div><p>fallback</p></div>",
    );
  });

  it("matches a marker preceded by other attributes", () => {
    const template =
      '<div><div class="card-body" data-bascik-slot><p>fallback</p></div></div>';
    expect(replaceDefaultSlots(template, "<p>custom</p>")).toBe(
      "<div><p>custom</p></div>",
    );
  });

  it("balances nested same-tag elements inside the fallback", () => {
    const template =
      "<section><div data-bascik-slot><div>fallback</div></div></section>";
    expect(replaceDefaultSlots(template, "<p>filled</p>")).toBe(
      "<section><p>filled</p></section>",
    );
    expect(replaceDefaultSlots(template, "")).toBe(
      "<section><div>fallback</div></section>",
    );
  });

  it("does not touch named slot markers", () => {
    const template =
      '<div><span data-bascik-slot="side"><p>side fallback</p></span></div>';
    expect(replaceDefaultSlots(template, "<p>content</p>")).toBe(template);
  });
});

describe("extractDefaultSlotContent", () => {
  it("strips named slot wrappers, keeping remaining content", () => {
    const inner =
      '<p>body</p><div data-bascik-slot="sidebar"><nav>nav</nav></div>';
    expect(extractDefaultSlotContent(inner)).toBe("<p>body</p>");
  });

  it("returns full content when there are no named slot wrappers", () => {
    expect(extractDefaultSlotContent("<p>content</p>")).toBe("<p>content</p>");
  });

  it("returns empty string for empty input", () => {
    expect(extractDefaultSlotContent("")).toBe("");
  });

  it("strips multiple named slot wrappers", () => {
    const inner =
      "<p>main</p>" +
      '<div data-bascik-slot="a"><span>a</span></div>' +
      '<div data-bascik-slot="b"><span>b</span></div>';
    expect(extractDefaultSlotContent(inner)).toBe("<p>main</p>");
  });

  it("strips named slot wrapper containing nested same-tag elements", () => {
    // Slot wrapper is <div>. Content has inner <div>s — must strip whole wrapper.
    const inner =
      "<p>default</p>" +
      '<div data-bascik-slot="side"><div style="inner"><span>s</span></div></div>';
    expect(extractDefaultSlotContent(inner)).toBe("<p>default</p>");
  });

  it("trims surrounding whitespace from slot content", () => {
    expect(extractDefaultSlotContent("\n  code here\n")).toBe("code here");
  });

  it("trims whitespace left after named slot wrappers are removed", () => {
    const inner =
      "\n  <p>main</p>\n  " +
      '<div data-bascik-slot="a"><span>a</span></div>' +
      "\n";
    expect(extractDefaultSlotContent(inner)).toBe("<p>main</p>");
  });

  it("preserves nested child named-slot markup in the parent default slot", () => {
    const inner =
      '<p>parent content</p><inner-demo><div data-bascik-slot="source-html">child content</div></inner-demo>';

    expect(extractDefaultSlotContent(inner, new Set(["inner-demo"]))).toBe(
      inner,
    );
  });
});

describe("listComponents", () => {
  it("treats a missing default src/components directory as no components", async () => {
    // The test cwd is pkg/, which has no src/components, and the config is the default.
    invalidateComponentListCache();
    await expect(listComponents()).resolves.toEqual({});
  });

  it("emits compatibility warnings with file and line numbers when loading components with unsupported patterns", async () => {
    const cwd = await mkdtemp(join(tmpdir(), "bascik-compat-warn-"));
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    try {
      await mkdir(join(cwd, "src/components/bad-card"), { recursive: true });
      await writeFile(
        join(cwd, "src/components/bad-card/bad-card.html"),
        '<div id="box"></div>\n<script>\n  const el = document.getElementById("box");\n  el.id = "mutated";\n</script>\n',
      );
      await writeFile(
        join(cwd, "src/components/bad-card/bad-card.css"),
        "[data-state] {\n  color: red;\n}\n",
      );
      await listComponents([join(cwd, "src/components")]);
      const calls = warnSpy.mock.calls.map((c) => c.join(" "));
      expect(
        calls.some(
          (msg) =>
            msg.includes("js-id-setter") && msg.includes("bad-card.html:4"),
        ),
      ).toBe(true);
      expect(
        calls.some(
          (msg) =>
            msg.includes("css-attribute-selector") &&
            msg.includes("bad-card.css:1"),
        ),
      ).toBe(true);
    } finally {
      warnSpy.mockRestore();
      await rm(cwd, { recursive: true, force: true });
    }
  });
});

describe("readComponentRoot", () => {
  const withProject = async (run: (cwd: string) => Promise<void>) => {
    const cwd = await mkdtemp(join(tmpdir(), "bascik-component-root-"));
    try {
      await run(cwd);
    } finally {
      await rm(cwd, { recursive: true, force: true });
    }
  };

  it("returns no files for a missing default root", async () => {
    await withProject(async (cwd) => {
      await expect(
        readComponentRoot(join(cwd, "src/components"), cwd),
      ).resolves.toEqual([]);
    });
  });

  it("names a missing configured root and the config key", async () => {
    await withProject(async (cwd) => {
      const error = await readComponentRoot(
        join(cwd, "src/widgets"),
        cwd,
      ).catch((caught) => caught);
      expect(error).toBeInstanceOf(Error);
      expect(error.message).toContain(
        'components directory "src/widgets" does not exist',
      );
      expect(error.message).toContain("directory.components");
      expect(error.cause).toMatchObject({ code: "ENOENT" });
    });
  });

  it("names a missing root outside the project by its relative path", async () => {
    await withProject(async (cwd) => {
      const error = await readComponentRoot(
        join(cwd, "../shared-components-missing"),
        join(cwd, "site"),
      ).catch((caught) => caught);
      expect(error.message).toContain(
        '"../../shared-components-missing" does not exist',
      );
    });
  });

  it("rejects a default root that is a file rather than treating it as empty", async () => {
    await withProject(async (cwd) => {
      await mkdir(join(cwd, "src"), { recursive: true });
      await writeFile(join(cwd, "src/components"), "not a directory");
      await expect(
        readComponentRoot(join(cwd, "src/components"), cwd),
      ).rejects.toThrow(
        'components directory "src/components" is not a directory',
      );
    });
  });

  it("lists component files in an existing root", async () => {
    await withProject(async (cwd) => {
      await mkdir(join(cwd, "src/components/cards"), { recursive: true });
      await writeFile(
        join(cwd, "src/components/cards/promo-card.html"),
        "<div></div>",
      );
      await writeFile(join(cwd, "src/components/notes.md"), "ignored");
      await expect(
        readComponentRoot(join(cwd, "src/components"), cwd),
      ).resolves.toEqual([join(cwd, "src/components/cards/promo-card.html")]);
    });
  });

  it.skipIf(process.platform === "win32" || process.getuid?.() === 0)(
    "keeps the original error for an unreadable default root",
    async () => {
      await withProject(async (cwd) => {
        const root = join(cwd, "src/components");
        await mkdir(root, { recursive: true });
        await chmod(root, 0o000);
        try {
          await expect(readComponentRoot(root, cwd)).rejects.toMatchObject({
            code: "EACCES",
          });
        } finally {
          await chmod(root, 0o755);
        }
      });
    },
  );
});

