// Bug 2: quote-aware props & attribute scanning
// ─────────────────────────────────────────────────────────────────────────────

describe("extractProps – single-quoted values", () => {
  it("extracts a single-quoted prop value", () => {
    expect(
      extractProps("<my-comp data-bascik-prop-title='Hi'></my-comp>"),
    ).toEqual({ title: "Hi" });
  });

  it("extracts mixed single- and double-quoted prop values", () => {
    expect(
      extractProps(
        `<my-comp data-bascik-prop-title='Hi' data-bascik-prop-href="/about"></my-comp>`,
      ),
    ).toEqual({ title: "Hi", href: "/about" });
  });

  it("extracts a single-quoted value containing double quotes", () => {
    expect(
      extractProps(`<my-comp data-bascik-prop-title='say "hi"'></my-comp>`),
    ).toEqual({ title: 'say "hi"' });
  });
});

describe("extractInheritableAttributes – quote-aware scanning", () => {
  it("does not end the open tag at a > inside a double-quoted value", () => {
    expect(
      extractInheritableAttributes(
        '<my-comp title="a > b" class="sticky"></my-comp>',
      ),
    ).toEqual({ title: "a > b", class: "sticky" });
  });

  it("does not end the open tag at a > inside a single-quoted value", () => {
    expect(
      extractInheritableAttributes(
        "<my-comp title='a > b' class=\"sticky\"></my-comp>",
      ),
    ).toEqual({ title: "a > b", class: "sticky" });
  });

  it("accepts single-quoted attribute values", () => {
    expect(
      extractInheritableAttributes("<my-nav class='sticky'></my-nav>"),
    ).toEqual({ class: "sticky" });
  });

  it("keeps extracting attributes after one with > in its value", () => {
    const result = extractInheritableAttributes(
      '<my-nav data-tip="1 > 0" aria-label="nav" id="top"></my-nav>',
    );
    expect(result).toEqual({
      "data-tip": "1 > 0",
      "aria-label": "nav",
      id: "top",
    });
  });
});

describe("injectProps – quote-aware scanning", () => {
  it("matches the marker element when a previous attribute value contains >", () => {
    const template = '<p title="a > b" data-bascik-prop-title></p>';
    expect(injectProps(template, { title: "Hi" })).toBe(
      '<p title="a > b">Hi</p>',
    );
  });

  it("matches the marker element when a following attribute value contains >", () => {
    const template = '<p data-bascik-prop-title data-tip="1 > 0"></p>';
    expect(injectProps(template, { title: "Hi" })).toBe(
      '<p data-tip="1 > 0">Hi</p>',
    );
  });

  it("supports single-quoted attribute values on the marker element", () => {
    const template = "<p class='lead' data-bascik-prop-title></p>";
    expect(injectProps(template, { title: "Hello" })).toBe(
      "<p class='lead'>Hello</p>",
    );
  });

  it("preserves a child component prop declaration and its content", () => {
    const template = "<p data-bascik-prop-title='featured'></p>";
    expect(injectProps(template, { title: "Hi" })).toBe(template);
  });

  // Misuse lens: unbalanced quotes around a receiver. The fallback content a
  // receiver loses can hold the quote that closes an attribute value the
  // close finder reads the rest of the template through, so the result is
  // the one a fresh scan of each spliced string gives (pinned against the
  // splice-per-receiver implementation).
  it("misuse: removed fallback content that closes a quoted value leaves the next receiver as a fresh scan does", () => {
    expect(
      injectProps(
        `<x="<b data-bascik-prop-t>""</B><b data-bascik-prop-t></b>`,
        { t: "v" },
      ),
    ).toBe(`<x="<b>v</B><b></b>`);
    expect(
      injectProps(
        `<i' data-bascik-prop-t x='>'</i><my-card data-bascik-prop-t></my-card>`,
        { t: "v" },
      ),
    ).toBe(`<i' x='>v</i><my-card></my-card>`);
  });

  it("still fills every receiver when the removed fallback holds balanced quotes in text", () => {
    expect(
      injectProps(
        `<p data-bascik-prop-t>it's "quoted"</p><b data-bascik-prop-t>'</b>`,
        { t: "v" },
      ),
    ).toBe(`<p>v</p><b>v</b>`);
  });

  // Misuse lens: a marker spelled with U+212A KELVIN SIGN, which
  // toLowerCase folds to "k". The receiver test lowercases names, so the
  // tag prefilter must never skip a tag that test accepts.
  it("misuse: a receiver whose name has a Kelvin sign is filled, as its lowercased name matches", () => {
    expect(injectProps(`<p data-bascik-prop-K></p>`, { k: "V" })).toBe(
      `<p>V</p>`,
    );
    expect(
      injectProps(`<p data-bascik-prop-t></p><b data-basciK-prop-t></b>`, {
        t: "V",
      }),
    ).toBe(`<p>V</p><b>V</b>`);
  });
});

// Regression: the quote-aware ATTR_VALUE scan previously used
// `(?:"[^"]*"|'[^']*'|[^>])*`, whose ambiguous alternation (`[^>]` also
// matches quote characters) backtracked exponentially when the rest of the
// pattern could not match.  A component whose prop-marker element had no
// balancing close tag (e.g. the marker's `<span>` was consumed but the
// closing `</span>` never followed in the scanned string) would hang the
// build for minutes.  These tests must complete in milliseconds.
describe("injectProps – does not hang on unbalanced markup", () => {
  it("returns quickly when a balanced marker is followed by a long unclosed tag", () => {
    // The balanced <span> is injected; the trailing unclosed <div class="…">
    // (no `>`) must not send the regex into exponential backtracking.
    const template =
      '<span data-bascik-prop-lang>x</span><div class="' +
      "a".repeat(4000) +
      '">';
    expect(injectProps(template, { lang: "js" })).toBe(
      '<span>js</span><div class="' + "a".repeat(4000) + '">',
    );
  });

  it("returns quickly when the marker element has no closing tag", () => {
    // Marker <span> is opened but `</span>` never appears before the string
    // ends.  injectProps only rewrites balanced marker elements, so here the
    // value is intentionally NOT injected; the leftover valueless marker is
    // stripped by the trailing cleanup pass, leaving the inner content intact.
    const rest = '<div class="y">"quoted"</div>'.repeat(500);
    const template = "<span data-bascik-prop-lang>" + rest;
    expect(injectProps(template, { lang: "js" })).toBe("<span>" + rest);
  });

  it("returns quickly when no element carries the marker", () => {
    const template =
      "<p>static</p>" + '<div class="x">"quoted"</div>'.repeat(500);
    expect(injectProps(template, { title: "Hi" })).toBe(template);
  });
});

describe("extractInheritableAttributes – does not hang on unbalanced markup", () => {
  it("returns quickly when the opening tag is never closed", () => {
    const content = "<div " + 'a="b" '.repeat(5000); // no `>` anywhere
    expect(extractInheritableAttributes(content)).toEqual({});
  });
});

