// Property-based fuzzing
// ─────────────────────────────────────────────────────────────────────────────

import fc from "fast-check";

describe("getTag / getFirstComponent / replaceTag – property-based fuzzing", () => {
  const compNameArb = fc.constantFrom(
    "my-card",
    "site-nav",
    "feature-row",
    "alert-box",
    "user-profile",
  );

  const innerContentArb = fc.constantFrom(
    "",
    "<p>hello</p>",
    '<span id="x">hi</span>',
    '<div class="wrap"><p>nested</p></div>',
    "<!-- comment -->",
    '<br /><img src="x.png" />',
    "<p>line 1</p>\n<p>line 2</p>",
    "<p data-bascik-slot>fallback</p>",
  );

  const attrArb = fc.constantFrom(
    "",
    ' class="highlight"',
    ' id="main"',
    ' data-bascik-prop-title="Hello"',
    ' class="a b" id="root"',
  );

  it("getTag does not throw on generated HTML and does not return sentinels", () => {
    fc.assert(
      fc.property(
        compNameArb,
        innerContentArb,
        attrArb,
        (name, inner, attrs) => {
          const html = `<${name}${attrs}>${inner}</${name}>`;
          expect(() => getTag(html, name)).not.toThrow();
          const result = getTag(html, name);
          expect(typeof (result.content ?? "")).toBe("string");
          expect(result.content ?? "").not.toContain("\x00");
        },
      ),
      { numRuns: 150 },
    );
  });

  it("replaceTag does not throw and output contains replacement", () => {
    fc.assert(
      fc.property(
        compNameArb,
        innerContentArb,
        attrArb,
        (name, inner, attrs) => {
          const original = `<${name}${attrs}>${inner}</${name}>`;
          const replacement = `<div>replaced</div>`;
          expect(() => replaceTag(original, name, replacement)).not.toThrow();
          const result = replaceTag(original, name, replacement);
          expect(result).toContain("replaced");
          expect(result).not.toContain(`<${name}`);
        },
      ),
      { numRuns: 150 },
    );
  });

  it("getFirstComponent returns the known component name or an empty object", () => {
    fc.assert(
      fc.property(
        compNameArb,
        innerContentArb,
        attrArb,
        (name, inner, attrs) => {
          const html = `<section><${name}${attrs}>${inner}</${name}></section>`;
          const componentList: ComponentList = {
            [name]: {
              fileName: `components/${name}.html`,
              fileContent: `<div>${inner}</div>`,
            },
          };
          expect(() => getFirstComponent(html, componentList)).not.toThrow();
          const result = getFirstComponent(html, componentList);
          if (result.name) expect(result.name).toBe(name);
        },
      ),
      { numRuns: 150 },
    );
  });

  it("replaceTag with $-containing replacement does not throw or lose content", () => {
    // Regression target: String.replace treats $1, $& etc as capture-group refs.
    fc.assert(
      fc.property(
        compNameArb,
        fc.constantFrom("$1", "$&", "$'", "$$", "$`"),
        (name, dollarStr) => {
          const original = `<${name}>inner</${name}>`;
          const replacement = `<p>${dollarStr}</p>`;
          expect(() => replaceTag(original, name, replacement)).not.toThrow();
          const result = replaceTag(original, name, replacement);
          expect(result).toContain(dollarStr);
        },
      ),
      { numRuns: 50 },
    );
  });
});

describe("injectProps – adversarial prop values", () => {
  it("escapes prop values that contain markup", () => {
    expect(
      injectProps("<p data-bascik-prop-label></p>", {
        label: "<script>alert(1)</script>",
      }),
    ).toBe("<p>&lt;script&gt;alert(1)&lt;/script&gt;</p>");
  });

  it("round-trips entity-encoded quotes through safe injection", () => {
    const props = extractProps(
      '<my-comp data-bascik-prop-label="say &quot;hello&quot; and it&#39;s fine"></my-comp>',
    );

    expect(injectProps("<p data-bascik-prop-label></p>", props)).toBe(
      "<p>say &quot;hello&quot; and it&#39;s fine</p>",
    );
  });

  it("does not throw and prop values with special chars are safely injected", () => {
    const propValueArb = fc.constantFrom(
      "Hello world",
      "It's a test",
      "<em>bold</em>",
      "$1 and $& and $'",
      "100% done",
      "A \u003e B",
      "line1\nline2",
      "",
      "bascik__comp__x",
      "data-bascik-prop-title",
    );

    const templateArb = fc.constantFrom(
      "<strong data-bascik-prop-label></strong>",
      "<p data-bascik-prop-label>fallback</p>",
      '<span data-bascik-prop-label="default"></span>',
      '<div class="wrap"><em data-bascik-prop-label></em></div>',
    );

    fc.assert(
      fc.property(propValueArb, templateArb, (value, template) => {
        expect(() => injectProps(template, { label: value })).not.toThrow();
        const result = injectProps(template, { label: value });
        expect(typeof result).toBe("string");
        // No prop markers should remain for a prop that was provided
        expect(result).not.toMatch(/data-bascik-prop-label(?=[>\s])/);
      }),
      { numRuns: 100 },
    );
  });
});

describe("tagName Validation Guards", () => {
  it("rejects malicious, unescaped, or non-conforming tagNames in findOpenTag, replaceTag, and getTag", () => {
    const maliciousNames = [
      "p(hello)",
      "p; alert(1)",
      "p[attr]",
      "p*",
      "a|b",
      "a+b",
      "p\\",
      "p/a",
      "div>",
      "<script",
      "\\w+",
      "div\\s*",
    ];

    const html = "<div>content</div><span>other</span>";

    for (const badName of maliciousNames) {
      // replaceTag should return the input string unchanged
      expect(replaceTag(html, badName, "REPLACED")).toBe(html);

      // getTag should return an empty object
      expect(getTag(html, badName)).toEqual({});
    }
  });

  it("filters out invalid component keys in getFirstComponent", () => {
    const html = "<valid-comp>content</valid-comp>";
    const invalidComponentList = {
      "invalid(tag)": { fileName: "components/invalid.html", fileContent: "1" },
      "valid-comp": { fileName: "components/valid.html", fileContent: "2" },
    };

    const result = getFirstComponent(html, invalidComponentList);
    expect(result.name).toBe("valid-comp");
  });

  it("ignores non-alphanumeric/regex-like propNames in injectProps", () => {
    const html = "<p data-bascik-prop-x>content</p>";
    // Prop name with malicious regexp characters
    const result = injectProps(html, { "x>": "injected", x: "good" });
    expect(result).toContain("good");
    expect(result).not.toContain("injected");
  });
});

describe("masked string caching performance helpers", () => {
  const componentList: ComponentList = {
    "my-card": { fileContent: "<div>card</div>" },
  };

  it("getFirstComponent utilizes pre-masked cached string when provided", () => {
    const html = "<script><my-card></my-card></script><my-card></my-card>";
    // If we mask it fully, it will find no components. Let's pass a custom masked string where everything is space-filled (meaning no tags).
    const customMasked = " ".repeat(html.length);
    expect(getFirstComponent(html, componentList, customMasked)).toEqual({});
  });

  it("getTag utilizes pre-masked cached string when provided", () => {
    const html = "<my-card></my-card>";
    // If we mask it fully, getTag won't see any open tag inside the masked string
    const customMasked = " ".repeat(html.length);
    expect(getTag(html, "my-card", componentList, customMasked)).toEqual({});
  });

  it("replaceTag utilizes pre-masked cached string when provided", () => {
    const html = "<my-card></my-card>";
    // If we mask it fully, replaceTag won't see any open tag inside the masked string
    const customMasked = " ".repeat(html.length);
    expect(
      replaceTag(html, "my-card", "<div>injected</div>", customMasked),
    ).toBe(html);
  });

  it("getFirstComponent caches regex compilation for repeated calls on the same ComponentList", () => {
    const list: ComponentList = {
      "my-card": { fileContent: "<div>card</div>" },
      "my-button": { fileContent: "<button>btn</button>" },
    };
    const html1 = "<my-card></my-card>";
    const html2 = "<my-button></my-button>";
    expect(getFirstComponent(html1, list).name).toBe("my-card");
    expect(getFirstComponent(html2, list).name).toBe("my-button");
    // Repeating on the same ComponentList object should return consistent results
    expect(getFirstComponent(html1, list).name).toBe("my-card");
  });
});

describe("createMatchingCloseFinder", () => {
  // Strings where the depth count is easy to get wrong: closes and opens
  // inside quoted and unquoted attribute values, self-closing same-name tags,
  // raw text, comments, mixed case, a close with whitespace, and unclosed or
  // over-closed runs.
  const samples = [
    '<i a="</i>">x<i>y</i></i></i>',
    "<i><i/><I>a</i ></I><i b='<i>'>c</i>",
    "<i><script></i></script></i><!-- </i> --></i>",
    "<i x=</i>>q</i><i>r<i>s</i>",
    "<i><i><i></i>",
    "</i></i><i>t</i></i>",
    "<i title=\"<i>\"><i data-x='</i>'></i></i><i>",
    "<i\n data-a='1'\n>m</i\t><textarea><i></textarea></i>",
  ];
  it.each(samples)(
    "agrees with a depth count from every position of %j",
    (html) => {
      const masked = maskRawTextContent(html);
      const find = createMatchingCloseFinder(html, masked);
      for (const tag of ["i", "I", "b"])
        for (let start = 0; start <= html.length; start++)
          expect([tag, start, find(tag, start)]).toEqual([
            tag,
            start,
            findMatchingClose(
              html,
              tag,
              start,
              masked,
              createAttributeValueScanner(masked),
            ),
          ]);
    },
  );

  it("misuse: an invalid tag name finds nothing instead of throwing", () => {
    const html = "<i>a</i>";
    const find = createMatchingCloseFinder(html, maskRawTextContent(html));
    expect(find("i)(", 3)).toBe(-1);
    expect(find("", 3)).toBe(-1);
  });
});
